public sealed class RetailNpcUserStatSourceCatalogTests
{
    [Fact]
    public void WholeSyntheticSourceIsAdmittedBeforeAnyRecordIsRetained()
    {
        using var f=new StatSourceFixture();C.Catalog c=C.Read(f.Request());
        Assert.False(c.ActivationReady);Assert.Equal(62,c.AllDefinitions.Length);
        foreach(var coverage in c.Coverage)
        {Assert.Equal(new C.Counts(11,31,13,8,262),new(coverage.Files,coverage.Records,coverage.Items,coverage.Skills,coverage.Functions));Assert.Empty(coverage.DuplicateKeys);}
        foreach(var row in c.AllDefinitions)
        {var record=c.Retain(row.Key);Assert.Equal(row.RawSha256,C.Hash(record.Raw.AsSpan()));Assert.Equal(row.Length,record.Raw.Length);Assert.Equal(row.OrderedChildTags.ToArray(),record.Read().Elements().Select(x=>x.Name.LocalName).ToArray());}
    }

    [Fact]
    public void PrivateCatalogAndRecordCannotBeForgedWithARecordCopyOrPublicConstructor()
    {
        foreach(Type t in new[]{typeof(C.Catalog),typeof(C.Catalog.Record),typeof(M.Projection)})
        {Assert.True(t.IsSealed);Assert.Empty(t.GetConstructors(BindingFlags.Public|BindingFlags.Instance));Assert.Null(t.GetMethod("<Clone>$"));}
        using var f=new StatSourceFixture();C.Catalog c=C.Read(f.Request());var record=c.Retain(StatSourceFixture.Key("Item","100001286"));
        XElement first=record.Read();first.SetAttributeValue("id","1");Assert.Equal("100001286",record.Read().Attribute("id")!.Value);
    }

    [Fact]
    public void AlreadyOwnedBytesSurviveSourceChangeButANewRetentionRejectsIt()
    {
        using var f=new StatSourceFixture();C.Catalog c=C.Read(f.Request());var k=StatSourceFixture.Key("Item","100001286");var raw=c.Retain(k);
        File.AppendAllText(f.SourcePath(C.Authority.CSharp,"items/item_templates.xml")," ");
        Assert.Equal(raw.Metadata.RawSha256,C.Hash(raw.Raw.AsSpan()));Assert.NotNull(raw.Read());Assert.Throws<GI.Domain>(()=>c.Retain(k));
    }

    [Theory]
    [InlineData("manifest")][InlineData("counts")][InlineData("country")][InlineData("missing")]
    [InlineData("sourcehash")][InlineData("extraimport")][InlineData("path")][InlineData("jsonduplicate")]
    [InlineData("unknownkey")][InlineData("truncated")][InlineData("utf8")][InlineData("duplicateattr")]
    [InlineData("dtd")][InlineData("depth")][InlineData("latebadfile")][InlineData("bounds")]
    [InlineData("key")][InlineData("singular")][InlineData("levelduplicate")][InlineData("unclassified")]
    public void WholeAdmissionRejectsBadOrIncompleteInput(string defect)
    {
        using var f=new StatSourceFixture();C.Request r=f.Request();
        switch(defect)
        {
            case "manifest":r=r with{ManifestSha256=new('f',64)};break;
            case "counts":r=r with{CSharpExpected=r.CSharpExpected with{Functions=261}};break;
            case "country":File.WriteAllText(Path.Combine(f.CSharpRoot,"config/main/gameserver.properties"),"gameserver.country.code=1\n");f.Publish();r=f.Request();break;
            case "missing":File.Delete(f.SourcePath(C.Authority.CSharp,"stats/absolute_stats.xml"));break;
            case "sourcehash":File.AppendAllText(f.SourcePath(C.Authority.CSharp,"stats/absolute_stats.xml")," ");break;
            case "extraimport":File.AppendAllText(Path.Combine(f.CSharpRoot,"data/static_data/static_data.xml")," ");break;
            case "path":f.Manifest!["files"]![0]!["relative"]="../outside.xml";r=f.WriteManifest();break;
            case "jsonduplicate":r=f.RawManifest(File.ReadAllText(f.ManifestPath).Replace("\"selection\":", "\"selection\":{},\"selection\":"));break;
            case "unknownkey":f.Manifest!["unreviewed_policy"]=true;r=f.WriteManifest();break;
            case "truncated":f.Xml("items/item_templates.xml",s=>s[..^20]);r=f.Request();break;
            case "utf8":f.Bytes("items/item_templates.xml",[0xc3,0x28]);r=f.Request();break;
            case "duplicateattr":f.Xml("items/item_templates.xml",s=>s.Replace("id=\"100001286\"","id=\"100001286\" id=\"1\""));r=f.Request();break;
            case "dtd":f.Xml("stats/absolute_stats.xml",s=>s.Replace("<absolute_stats>","<!DOCTYPE absolute_stats [<!ENTITY x 'x'>]><absolute_stats>"));r=f.Request();break;
            case "depth":f.Xml("stats/absolute_stats.xml",s=>s.Replace("</absolute_stats>",string.Concat(Enumerable.Repeat("<x>",70))+string.Concat(Enumerable.Repeat("</x>",70))+"</absolute_stats>"));r=f.Request();break;
            case "latebadfile":f.Xml("stats/absolute_stats.xml",s=>s+"<late/>");r=f.Request();break;
            case "bounds":r=r with{MaxTotalBytes=1};break;
            case "key":f.Xml("items/item_templates.xml",s=>s.Replace("id=\"100001286\"","id=\"\""));r=f.Request();break;
            case "singular":f.Xml("items/item_templates.xml",s=>s.Replace("<item_template id=\"900002\" item_group=\"HEAD\">","<item_template id=\"900002\" item_group=\"HEAD\"><improve/><improve/>"));r=f.Request();break;
            case "levelduplicate":f.Xml("enchants/enchant_templates.xml",s=>s.Replace("</enchant_list>","<enchant_data level=\"5\"/></enchant_list>"));r=f.Request();break;
            case "unclassified":f.AddFile("unclassified.xml","<rows><row><modifiers><add name=\"MAXHP\" value=\"1\"/></modifiers></row></rows>");r=f.Request(files:12);break;
        }
        Assert.Throws<GI.Domain>(()=>C.Read(r));
    }

    [Fact]
    public void NullAndUnknownCallerContractsRejectWithoutPublishingCatalog()
    {
        Assert.Throws<GI.Domain>(()=>C.Read(null!));using var f=new StatSourceFixture();
        Assert.Throws<GI.Domain>(()=>C.Read(f.Request() with{Origin=(C.Origin)999}));
        Assert.Throws<GI.Domain>(()=>C.Read(f.Request() with{MaxRecordBytes=262145}));
    }

    [Fact]
    public void WithinFileLastMapAndFirstCpSelectionRemainDistinctAndDefinitionsAreRetained()
    {
        using var f=new StatSourceFixture();
        f.Xml("items/item_templates.xml",s=>s.Replace("</item_templates>","<item_template id=\"100001286\" name=\"last-definition\"/></item_templates>"));
        string cp=f.Files["conqueror_protector_ranks/conqueror_protector_ranks.xml"];
        XElement first=XElement.Parse(cp).Elements().First();string id=first.Attribute("rank_num")!.Value,kind=first.Attribute("type")!.Value;
        first.SetAttributeValue("unconsumed_note","last-cp-definition");f.Xml("conqueror_protector_ranks/conqueror_protector_ranks.xml",s=>s.Replace("</conqueror_protector_ranks>",first+"</conqueror_protector_ranks>"));
        C.Catalog c=C.Read(f.Request(records:33,items:14,functions:262+first.Descendants().Count(C.FunctionNode)));
        var item=StatSourceFixture.Key("Item","100001286");Assert.Equal(2,c.Definitions(item).Length);Assert.Equal("last-definition",c.Retain(item).Read().Attribute("name")!.Value);
        var key=StatSourceFixture.Key("Cp",id,kind);Assert.Equal(2,c.Definitions(key).Length);Assert.Null(c.Retain(key).Read().Attribute("unconsumed_note"));
    }

    [Fact]
    public void SetMembershipUsesLastActualPartMembershipRatherThanItemSetIdOrAName()
    {
        using var f=new StatSourceFixture();f.Xml("item_sets/item_sets.xml",s=>s.Replace("</item_sets>","<itemset id=\"900004\"><itempart itemid=\"110100919\"/></itemset></item_sets>"));
        var c=C.Read(f.Request(records:32));Assert.Equal("900004",c.SetForItem(C.Authority.CSharp,"110100919")!.Key.Primary);
        Assert.Equal("1",c.SetForItem(C.Authority.CSharp,"113100831")!.Key.Primary);
    }

    [Fact]
    public void LegacyPinnedSourceAdmissionIsNotWidenedByTheNewCatalog()
    {
        using var f=new StatSourceFixture();var c=C.Read(f.Request());var row=c.Retain(StatSourceFixture.Key("Item","900002"));
        Assert.Throws<GI.Domain>(()=>GI.SourceRecord.Admit("item_template-900002.xml",row.Metadata.FileSha256,row.Metadata.Start,row.Metadata.Start+row.Raw.Length,row.Raw.AsSpan()));
    }

    [SkippableFact]
    public void FullSelectedSourcesMatchAllIndependentRowsAndAllItemSkillIdentities()
    {
        string? path=Environment.GetEnvironmentVariable("AION_RETAIL_USER_STAT_SOURCE_MANIFEST");
        string? java=Environment.GetEnvironmentVariable("AION_RETAIL_USER_STAT_SOURCE_JAVA_ROOT");
        string? current=Environment.GetEnvironmentVariable("AION_RETAIL_USER_STAT_SOURCE_CSHARP_ROOT");
        string? ledger=Environment.GetEnvironmentVariable("AION_RETAIL_USER_STAT_SOURCE_RECORDS");
        Skip.If(string.IsNullOrWhiteSpace(path)||string.IsNullOrWhiteSpace(java)||string.IsNullOrWhiteSpace(current)||string.IsNullOrWhiteSpace(ledger),"Opt-in full selected source paths are required.");
        using(var input=File.OpenRead(ledger!))Assert.Equal(StatSourceFixture.Corpus.RootElement.GetProperty("source_records_ledger_sha256").GetString(),Convert.ToHexStringLower(SHA256.HashData(input)));
        string manifest=StatSourceFixture.Corpus.RootElement.GetProperty("full_manifest_sha256").GetString()!;
        var c=C.Read(new(path!,manifest,"catalog:"+manifest,java!,current!,C.Origin.SelectedSourceDeclaration,new(664,121851,102009,13570,348422),new(670,121851,102009,13570,348422),"reviewed-static-selected-source;not-runtime"));
        Assert.Equal(243702,c.AllDefinitions.Length);
        var javaRows=c.AllDefinitions.Where(x=>x.Key.Authority==C.Authority.Java).ToDictionary(x=>(x.Relative,x.DefinitionOrdinal));int rows=0;
        foreach(string line in File.ReadLines(ledger!))
        {
            using JsonDocument d=JsonDocument.Parse(line);var r=d.RootElement;string relative=r.GetProperty("source_relative").GetString()!;
            Assert.True(javaRows.TryGetValue((relative,r.GetProperty("record_ordinal").GetInt32()),out var actual));
            Assert.Equal(r.GetProperty("start_byte").GetInt64(),actual!.Start);Assert.Equal(r.GetProperty("end_byte_exclusive").GetInt64()-actual.Start,actual.Length);
            Assert.Equal(r.GetProperty("raw_sha256").GetString(),actual.RawSha256);Assert.Equal(r.GetProperty("source_sha256").GetString(),actual.FileSha256);
            Assert.Equal(r.GetProperty("function_rows").GetInt32(),actual.FunctionRows);Assert.Equal(r.GetProperty("import_ordinal").GetInt32(),actual.ImportOrdinal);
            Assert.Equal(r.GetProperty("child_tags").EnumerateArray().Select(x=>x.GetString()).ToArray(),actual.OrderedChildTags.ToArray());rows++;
        }
        Assert.Equal(121851,rows);
        // A real full catalog does not turn generic base StatFunction fields into a
        // reviewed custom producer. No fabricated small production catalog is used.
        var unsupported=M.Project(StatSourceFixture.Input(c,StatSourceFixture.Case("mixed-abs-debuff-first-registration")));
        Assert.Equal(M.Status.UnsupportedPrecondition,unsupported.Status);Assert.Null(unsupported.Candidate);
        foreach(var (family,label,count) in new[]{(C.Family.Item,"items",102009),(C.Family.Skill,"skills",13570)})
        {
            foreach(C.Authority a in Enum.GetValues<C.Authority>())
            {
                string[] ids=c.AllDefinitions.Where(x=>x.Key.Authority==a&&x.Key.Family==family).Select(x=>x.Key.Primary).Distinct().OrderBy(x=>int.Parse(x,CultureInfo.InvariantCulture)).ToArray();
                Assert.Equal(count,ids.Length);Assert.Equal(StatSourceFixture.Corpus.RootElement.GetProperty("full_id_set_sha256").GetProperty(label).GetString(),C.Hash(Encoding.UTF8.GetBytes(string.Join('\n',ids)+"\n")));
            }
        }
    }
}

// The compressed document is an independently generated Fraction/RNE oracle and conditional
// current-input corpus. C# code never calls the implementation to construct its expected values.
internal sealed class StatSourceFixture : IDisposable
{
    internal static readonly JsonDocument Corpus=ReadCorpus();
    private static JsonDocument ReadCorpus()
    {using var source=new MemoryStream(Convert.FromBase64String(""));using var unzip=new GZipStream(source,CompressionMode.Decompress);return JsonDocument.Parse(unzip);}
    internal static IEnumerable<JsonElement> Cases=>Corpus.RootElement.GetProperty("cases").EnumerateArray();
    internal static JsonElement Case(string label)=>Cases.Single(x=>x.GetProperty("label").GetString()==label);
    internal readonly string Root=Path.Combine(Path.GetTempPath(),"retail-source-fixture-"+Guid.NewGuid().ToString("N"));
    internal string JavaRoot=>Path.Combine(Root,"Java");internal string CSharpRoot=>Path.Combine(Root,"CSharp");
    internal string ManifestPath=>Path.Combine(Root,"manifest.json");
    internal readonly Dictionary<string,string> Files=new(StringComparer.Ordinal);
    private readonly Dictionary<string,byte[]> overrides=new(StringComparer.Ordinal);
    internal JsonObject? Manifest;
    internal StatSourceFixture()
    {foreach(var file in Corpus.RootElement.GetProperty("files").EnumerateArray())Files.Add(file.GetProperty("relative").GetString()!,file.GetProperty("xml").GetString()!);Publish();}
    internal string SourcePath(C.Authority a,string relative)=>Path.Combine(a==C.Authority.Java?JavaRoot:CSharpRoot,"data/static_data",relative.Replace('/',Path.DirectorySeparatorChar));
    internal void Xml(string relative,Func<string,string> mutate){Files[relative]=mutate(Files[relative]);Publish();}
    internal void Bytes(string relative,byte[] raw){overrides[relative]=raw;Publish();}
    internal void AddFile(string relative,string xml){Files.Add(relative,xml);Publish();}
    internal void Publish()
    {
        var rows=new JsonArray();var configs=new JsonObject();var entries=new JsonObject();
        foreach(C.Authority authority in Enum.GetValues<C.Authority>())
        {
            string root=authority==C.Authority.Java?JavaRoot:CSharpRoot;Directory.CreateDirectory(Path.Combine(root,"config/main"));Directory.CreateDirectory(Path.Combine(root,"data/static_data"));
            string config=Path.Combine(root,"config/main/gameserver.properties");if(!File.Exists(config))File.WriteAllText(config,"gameserver.country.code=99\n",new UTF8Encoding(false));
            configs[authority.ToString()]=new JsonObject{{"path",config},{"sha256",C.Hash(File.ReadAllBytes(config))}};
            XElement entry=new("static_data",Files.Keys.Select(x=>new XElement("import",new XAttribute("file",x))));string entryPath=Path.Combine(root,"data/static_data/static_data.xml");File.WriteAllText(entryPath,entry.ToString(),new UTF8Encoding(false));
            entries[authority.ToString()]=new JsonObject{{"path",entryPath},{"sha256",C.Hash(File.ReadAllBytes(entryPath))}};int ordinal=0;
            foreach(var (relative,xml) in Files)
            {
                string path=SourcePath(authority,relative);Directory.CreateDirectory(Path.GetDirectoryName(path)!);byte[] bytes=overrides.GetValueOrDefault(relative)??Encoding.UTF8.GetBytes(xml);File.WriteAllBytes(path,bytes);
                rows.Add(new JsonObject{{"import_ordinal",ordinal++},{"declared_import",relative},{"path",path},{"relative",relative},{"country",99},{"country_override",false},{"directory_order",0},{"authority",authority.ToString()},{"sha256",C.Hash(bytes)},{"bytes",bytes.Length},{"full_xml_parse",true},{"root_tag","synthetic"},{"top_level_records",0}});
            }
        }
        Manifest=new JsonObject{{"configs",configs},{"entries",entries},{"files",rows},{"selection",new JsonObject{{"origin","explicit-synthetic-conditional"}}}};WriteManifest();
    }
    internal C.Request Request(int files=11,int records=31,int items=13,int skills=8,int functions=262)
    {string hash=C.Hash(File.ReadAllBytes(ManifestPath));return new(ManifestPath,hash,"catalog:"+hash,JavaRoot,CSharpRoot,C.Origin.SyntheticFixture,new(files,records,items,skills,functions),new(files,records,items,skills,functions),"synthetic-source-bound-not-observed-current-account");}
    internal C.Request WriteManifest(){File.WriteAllText(ManifestPath,Manifest!.ToJsonString(),new UTF8Encoding(false));return Request();}
    internal C.Request RawManifest(string raw){File.WriteAllText(ManifestPath,raw,new UTF8Encoding(false));return Request();}
    internal static C.Key Key(string family,string primary,string secondary="")=>new(C.Authority.CSharp,Enum.Parse<C.Family>(family),primary,secondary);
    internal static string Text(JsonElement x,string key,string absent="")=>x.TryGetProperty(key,out var value)?value.GetString()??absent:absent;
    internal static int Int(JsonElement x,string key,int absent=0)=>x.TryGetProperty(key,out var value)?value.GetInt32():absent;
    internal static bool Bool(JsonElement x,string key,bool absent=false)=>x.TryGetProperty(key,out var value)?value.GetBoolean():absent;
    internal static GI.Binding Binding(string owner)=>new(owner,"generation:"+owner,"source-op","epoch0",new(N.FactKind.SourceBoundDeclaration,"conditional-current-input:"+owner));
    internal static GI.Floating Floating=>new(true,true,false,false,true);
    internal static C.Catalog.Record? Record(C.Catalog c,JsonElement refNode)
    {if(refNode.ValueKind==JsonValueKind.Null)return null;return c.Retain(Key(Text(refNode,"family"),Text(refNode,"primary"),Text(refNode,"secondary")));}
