        return new(known?GI.AbsRecipe.KnownCurrentPrivateField:GI.AbsRecipe.DefaultFalseUnchanged,known&&field.GetBoolean(),GI.AbsSource,"StatAbsFunction.debuff",owner.Owner,owner.Operation,owner.Epoch,!known,true,known);
    }
