            var pair=R.Factory(factory);C.Catalog.Record? item=args.TryGetProperty("item_source",out var source)?Record(catalog,source):null;
            registrations.Add(new(Text(r,"occurrence"),Int(r,"sequence"),owner,type,Record(catalog,r.GetProperty("source")),selection,true,actual,pair.Java,pair.CSharp,item,args.TryGetProperty("item_owner",out var io)?Binding(io.GetString()!):null,args.TryGetProperty("action_source",out var action)?Record(catalog,action):null,Bool(args,"fusion_random")));
        }
        var items=row.GetProperty("items").EnumerateArray().Select(i=>new M.Item(Binding(Text(i,"owner")),Record(catalog,i.GetProperty("source"))!,Int(i,"mask"),Bool(i,"equipped",true),R.OwnerType.Item,i.TryGetProperty("fusion",out _)?GI.Known.Present:GI.Known.Null,
            i.TryGetProperty("fusion",out var fusion)?Record(catalog,fusion):null,i.TryGetProperty("inventory_variant",out var iv)?iv.GetInt32():null,i.TryGetProperty("fusion_variant",out var fv)?fv.GetInt32():null,i.TryGetProperty("idian_action",out var action)?Record(catalog,action):null,i.TryGetProperty("idian_variant",out var av)?av.GetInt32():null,i.TryGetProperty("enchant_level",out var el)?el.GetInt32():null,i.TryGetProperty("temper_level",out var tl)?tl.GetInt32():null,i.TryGetProperty("plume_random",out var pr)?pr.GetInt32():null)).ToImmutableArray();
        var lists=row.GetProperty("stat_lists").EnumerateArray().Select(x=>new M.StatOrder(Text(x,"stat"),x.GetProperty("entries").EnumerateArray().Select(e=>e.GetString()!).ToImmutableArray())).ToImmutableArray();
        return new(catalog,Binding("actor-stat-registry"),R.Policy,true,true,true,true,true,registrations.ToImmutable(),items,lists,Floating);
    }
    internal static GI.GeneralStatFrame Frame(JsonElement row)
    {
        var charge=row.TryGetProperty("charge",out var charges)?charges.EnumerateObject().Select(p=>new GI.GeneralCharge(Binding(p.Name),p.Value.GetInt32())).ToImmutableArray():default;
        return new("source-op","epoch0",Binding("actor-stat-registry"),Int(row,"class",1),Int(row,"level",55),GI.ClassSource,Bool(row,"flying"),Bool(row,"state_flying"),Bool(row,"resting"),Bool(row,"walking"),false,false,Bool(row,"shield"),charge,Floating,IsStaff:false);
    }
    public void Dispose()
    {
        string parent=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
        string full=Path.GetFullPath(Root);if(!full.StartsWith(parent,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith("retail-source-fixture-",StringComparison.Ordinal))throw new InvalidOperationException("test cleanup containment");
        if(Directory.Exists(full))Directory.Delete(full,true);
    }
